7	 * Usage and reproduction in any manner whatsoever without the written permission of Daniel Carvalho Liedke is strictly forbidden.
8	 *
9	 * Purpose: Image attachment, paste, and display functionality
10	 *
11	 * *******************************************************************************************************************/
12	
13	using System;
14	using System.IO;
15	using System.Linq;
16	using System.Diagnostics;
17	using System.Collections.Generic;
18	using System.Windows;
19	using System.Windows.Input;
20	using System.Windows.Controls;
21	using System.Windows.Media.Imaging;
22	using Microsoft.Win32;
23	using static ClaudeCodeVS.UI.Loc;
24	
25	namespace ClaudeCodeVS
26	{
27	    public partial class ClaudeCodeControl
28	    {
29	        #region Image Fields
30	
31	        /// <summary>
32	        /// List of currently attached image file paths
33	        /// </summary>
34	        private readonly List<string> attachedImagePaths = new List<string>();
35	
36	        /// <summary>
37	        /// Counter for naming pasted images sequentially
38	        /// </summary>
39	        private int imageCounter = 1;
40	
41	        /// <summary>
42	        /// Edge length of the square thumbnail on an image attachment chip. The chip height and the
43	        /// decode resolution both follow from it, so this is the only value to change when tuning.
44	        /// </summary>
45	        private const int AttachmentThumbnailSize = 32;
46	
47	        #endregion
48	
49	        #region Image Paste and Attachment
50	
51	        /// <summary>
52	        /// Attempts to paste an image from the clipboard
53	        /// </summary>
54	        /// <returns>True if an image was successfully pasted, false otherwise</returns>
55	        private bool TryPasteImage()
56	        {
57	            if (!TrySaveClipboardImage(out string imagePath))
58	            {
59	                return false;
60	            }
61	
62	            attachedImagePaths.Add(imagePath);
63	            UpdateImageDropDisplay();
64	            return true;
65	        }
66	
67	        /// <summary>
68	        /// Writes the clipboard image (if there is one) to the session temp folder and reports where it
69	        /// landed. Split out of <see cref="TryPasteImage"/> so a chat tab can stage the file in its own
70	        /// attachment list instead of the panel's.
71	        /// </summary>
72	        private bool TrySaveClipboardImage(out string savedPath)
73	        {
74	            savedPath = null;
75	
76	            try
77	            {
78	                // Check if clipboard contains text first - if so, let normal text paste happen
79	                // This prevents Excel cells (which have both text and image formats) from pasting as images
80	                if (ClipboardRetrySync(() => Clipboard.ContainsText()))
81	                {
82	                    return false;
83	                }
84	
85	                BitmapSource image = null;
86	
87	                // Try different clipboard formats for images
88	                if (ClipboardRetrySync(() => Clipboard.ContainsImage()))
89	                {
90	                    image = ClipboardRetrySync(() => Clipboard.GetImage());
91	                }
92	                else if (ClipboardRetrySync(() => Clipboard.ContainsData(DataFormats.Bitmap)))
93	                {
94	                    var bitmapData = ClipboardRetrySync(() => Clipboard.GetData(DataFormats.Bitmap));
95	                    if (bitmapData is System.Drawing.Bitmap bitmap)
96	                    {
97	                        var handle = bitmap.GetHbitmap();
98	                        try
99	                        {
100	                            image = System.Windows.Interop.Imaging.CreateBitmapSourceFromHBitmap(
101	                                handle, IntPtr.Zero, System.Windows.Int32Rect.Empty,
102	                                BitmapSizeOptions.FromEmptyOptions());
103	                        }
104	                        finally
105	                        {
106	                            DeleteObject(handle);
107	                        }
108	                    }
109	                }
110	                else if (ClipboardRetrySync(() => Clipboard.ContainsData("PNG")))
111	                {
112	                    var pngData = ClipboardRetrySync(() => Clipboard.GetData("PNG")) as MemoryStream;
113	                    if (pngData != null)
114	                    {
115	                        image = BitmapFrame.Create(pngData);
116	                    }
117	                }
118	
119	                if (image != null)
120	                {
121	                    // Ensure temp directory exists
122	                    if (!Directory.Exists(tempImageDirectory))
123	                    {
124	                        Directory.CreateDirectory(tempImageDirectory);
125	                    }
126	
127	                    // Generate filename and save image
128	                    string fileName = $"image_{imageCounter}.png";
129	                    imageCounter++;
130	                    string imagePath = Path.Combine(tempImageDirectory, fileName);
131	
132	                    using (var fileStream = new FileStream(imagePath, FileMode.Create))
133	                    {
134	                        var encoder = new PngBitmapEncoder();
135	                        encoder.Frames.Add(BitmapFrame.Create(image));
136	                        encoder.Save(fileStream);
137	                    }
138	
139	                    savedPath = imagePath;
140	                    return true;
141	                }
142	            }
143	            catch (Exception ex)
144	            {
145	                Debug.WriteLine($"Error pasting image: {ex.Message}");
146	                MessageBox.Show(L("Error pasting image: {0}", ex.Message), L("Paste Error"), MessageBoxButton.OK, MessageBoxImage.Warning);
147	            }
148	
149	            return false;
150	        }
151	
152	        private void AttachDropdownButton_Click(object sender, RoutedEventArgs e)
153	        {
154	            if (AttachDropdownButton?.ContextMenu != null)
155	            {
156	                AttachDropdownButton.ContextMenu.PlacementTarget = AttachDropdownButton;
157	                AttachDropdownButton.ContextMenu.IsOpen = true;
158	            }
159	        }
160	
161	        private void AttachFileMenuItem_Click(object sender, RoutedEventArgs e)
162	            => ImageDropBorder_Click(sender, null);
163	
164	        /// <summary>
165	        /// Handles click on file drop border to open file selection dialog
166	        /// </summary>
167	        private void ImageDropBorder_Click(object sender, MouseButtonEventArgs e)
168	        {
169	            string[] chosen = PickAttachmentFiles();
170	            if (chosen == null)
171	            {
172	                return;
173	            }
174	
175	            foreach (string filename in chosen)
176	            {
177	                attachedImagePaths.Add(filename);
178	            }
179	            UpdateImageDropDisplay();
180	        }
181	
182	        /// <summary>
183	        /// Opens the attachment file dialog and returns what the user picked, or null when they
184	        /// cancelled. Split out of <see cref="ImageDropBorder_Click"/> so a chat tab can stage the
185	        /// files in its own attachment list instead of the panel's.
186	        /// </summary>
187	        private string[] PickAttachmentFiles()
188	        {
189	            try
190	            {
191	                // Open file dialog for file selection with common data formats
192	                OpenFileDialog openFileDialog = new OpenFileDialog
193	                {
194	                    Filter = L("All files (*.*)|*.*|" +
195	                             "Images (*.png;*.jpg;*.jpeg;*.gif;*.bmp;*.webp)|*.png;*.jpg;*.jpeg;*.gif;*.bmp;*.webp|" +
196	                             "Documents (*.pdf;*.doc;*.docx;*.txt;*.rtf)|*.pdf;*.doc;*.docx;*.txt;*.rtf|" +
197	                             "Spreadsheets (*.xls;*.xlsx;*.csv)|*.xls;*.xlsx;*.csv|" +
198	                             "Data (*.json;*.xml;*.yaml;*.yml)|*.json;*.xml;*.yaml;*.yml|" +
199	                             "Code (*.cs;*.py;*.js;*.java;*.cpp;*.h)|*.cs;*.py;*.js;*.java;*.cpp;*.h"),
200	                    Multiselect = true
201	                };
202	
203	                return openFileDialog.ShowDialog() == true ? openFileDialog.FileNames : null;
204	            }
205	            catch (Exception ex)
206	            {
207	                MessageBox.Show(L("Error selecting files: {0}", ex.Message), L("Error"), MessageBoxButton.OK, MessageBoxImage.Error);
208	                return null;
209	            }
210	        }
211	
212	        /// <summary>
213	        /// PreviewDragOver handler for the prompt textbox — accepts dropped files and shows
214	        /// the Copy cursor only when the payload actually contains file paths. Marked Handled
215	        /// so the textbox's default text-drop behavior doesn't override it.
216	        /// </summary>
217	        private void PromptTextBox_PreviewDragOver(object sender, DragEventArgs e)
218	        {
219	            if (e.Data != null && e.Data.GetDataPresent(DataFormats.FileDrop))
220	            {
221	                e.Effects = DragDropEffects.Copy;
222	            }
223	            else
224	            {
225	                e.Effects = DragDropEffects.None;
226	            }
227	            e.Handled = true;
228	        }
229	
230	        /// <summary>
231	        /// PreviewDrop handler for the prompt textbox — adds dropped files to the attachment
232	        /// list using the same path as the 📎 toolbar button. Directories are skipped (Claude
233	        /// can't attach folders directly); duplicates are filtered out.
234	        /// </summary>
235	        private void PromptTextBox_PreviewDrop(object sender, DragEventArgs e)
236	        {
237	            try
238	            {
239	                if (e.Data == null || !e.Data.GetDataPresent(DataFormats.FileDrop))
240	                {
241	                    return;
242	                }
243	
244	                var dropped = e.Data.GetData(DataFormats.FileDrop) as string[];
245	                if (dropped == null || dropped.Length == 0) return;
246	
247	                bool any = false;
248	                foreach (string path in dropped)
249	                {
250	                    if (string.IsNullOrEmpty(path)) continue;
251	                    if (Directory.Exists(path)) continue; // skip folders
252	                    if (!File.Exists(path)) continue;
253	                    if (attachedImagePaths.Contains(path)) continue;
254	
255	                    attachedImagePaths.Add(path);
256	                    any = true;
257	                }
258	
259	                if (any)
260	                {
261	                    UpdateImageDropDisplay();
262	                }
263	
264	                e.Handled = true;
265	            }
266	            catch (Exception ex)
267	            {
268	                Debug.WriteLine($"PromptTextBox_PreviewDrop error: {ex.Message}");
269	                MessageBox.Show(L("Error attaching dropped files: {0}", ex.Message),
270	                    L("Drag & Drop"), MessageBoxButton.OK, MessageBoxImage.Error);
271	            }
272	        }
273	
274	        #endregion
275	
276	        #region Image Display Management
277	
278	        /// <summary>
279	        /// Updates the UI to display currently attached images as chips
280	        /// </summary>
281	        private void UpdateImageDropDisplay()
282	        {
283	            AttachedImagesPanel.Children.Clear();
284	
285	            if (attachedImagePaths.Any())
286	            {
287	                foreach (var path in attachedImagePaths.ToList())
288	                {
289	                    AttachedImagesPanel.Children.Add(CreateAttachmentChip(path));
290	                }
291	            }
292	
293	            // The chat tab has its own attachment strip showing the same list.
294	            UpdateComposerAttachmentChips();
295	        }
296	
297	        /// <summary>
298	        /// Builds one attachment chip (file name + remove button). A fresh instance is created for
299	        /// every host because a WPF element can only live in one visual tree, and the panel and the
300	        /// chat composer both show the same attachments.
301	        /// </summary>
302	        private Border CreateAttachmentChip(string path)
303	        {
304	            return CreateAttachmentChip(path, p =>
305	            {
306	                attachedImagePaths.Remove(p);
307	                UpdateImageDropDisplay();
308	            });
309	        }
310	
311	        /// <summary>
312	        /// Same chip, but the caller says what removing it means. A chat tab owns its own attachment
313	        /// list, so its ✕ must not reach into the panel's.
314	        /// </summary>
315	        private Border CreateAttachmentChip(string path, Action<string> onRemove)
316	        {
317	            // Modern icon style: images get a card with the whole picture instead of the chip.
318	            if (_settings?.ChatIconStyle == ChatIconStyle.Modern
319	                && !string.IsNullOrEmpty(path) && IsImageFile(path) && File.Exists(path))
320	            {
321	                Border card = CreateAttachmentCard(path, onRemove);
322	                if (card != null)
323	                {
324	                    return card;
325	                }
326	            }
327	
328	            // Create chip border
329	            var chip = new Border
330	            {
331	                Style = (Style)FindResource("ChipBorder"),
332	                Cursor = Cursors.Hand,
333	                Tag = path
334	            };
335	
336	            // Make chip clickable to open image
337	            chip.MouseLeftButtonUp += (s, e) =>
338	            {
339	                // Don't open if clicking the remove button
340	                if (e.OriginalSource is Button)
341	                    return;
342	
343	                var imagePath = (string)((Border)s).Tag;
344	                try
345	                {
346	                    Process.Start(new ProcessStartInfo(imagePath) { UseShellExecute = true });
347	                }
348	                catch (Exception ex)
349	                {
350	                    MessageBox.Show(L("Error opening image: {0}", ex.Message), L("Error"), MessageBoxButton.OK, MessageBoxImage.Error);
351	                }
352	            };
353	
354	            // Create chip content
355	            var sp = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center };
356	
357	            // Image attachments get a small square thumbnail plus a bigger preview on hover.
358	            // The chip grows to fit it, since ChipBorder's own Height is sized for text alone.
359	            var thumbnail = CreateAttachmentThumbnail(path);
360	            if (thumbnail != null)
361	            {
362	                chip.Height = AttachmentThumbnailSize + 8;
363	                sp.Children.Add(thumbnail);
364	                UI.ImagePreview.AttachPreviewToolTip(chip, path);
365	            }
366	
367	            // Filename text - truncate if too long
368	            string fileName = Path.GetFileName(path);
369	            string displayName = fileName.Length > 18 ? fileName.Substring(0, 15) + "..." : fileName;
370	
371	            var nameBlock = new TextBlock
372	            {
373	                Text = displayName,
374	                VerticalAlignment = VerticalAlignment.Center,
375	                MaxWidth = 120,
376	                TextTrimming = TextTrimming.CharacterEllipsis,
377	                ToolTip = thumbnail != null ? null : fileName, // an image chip shows the preview instead
378	                FontSize = 11
379	            };
380	            nameBlock.SetResourceReference(TextBlock.ForegroundProperty, Microsoft.VisualStudio.Shell.VsBrushes.ToolWindowTextKey);
381	
382	            // Remove button
383	            var removeBtn = new Button
384	            {
385	                Style = (Style)FindResource("ChipRemoveButton"),
386	                Tag = path
387	            };
388	            removeBtn.Click += (s, e) =>
389	            {
390	                var p = (string)((Button)s).Tag;
391	                onRemove?.Invoke(p);
392	            };
393	
394	            sp.Children.Add(nameBlock);
395	            sp.Children.Add(removeBtn);
396	            chip.Child = sp;
397	
398	            return chip;
399	        }
400	
401	        /// <summary>
402	        /// Builds the small square thumbnail shown at the left of an image chip; the chip itself
403	        /// carries the larger hover preview. Returns null for non-image files or anything that fails
404	        /// to decode (a broken file must never stop the chip itself from appearing).
405	        /// </summary>
406	        private FrameworkElement CreateAttachmentThumbnail(string path)
407	        {
408	            try
409	            {
410	                if (string.IsNullOrEmpty(path) || !IsImageFile(path) || !File.Exists(path))
411	                {
412	                    return null;
413	                }
414	
415	                // Decoded at 2x the display size so the chip stays crisp on a 200% DPI monitor.
416	                var bitmap = UI.ImagePreview.LoadBitmap(path, AttachmentThumbnailSize * 2);
417	                if (bitmap == null) return null;
418	
419	                // UniformToFill inside a fixed square crops instead of letterboxing, so wide
420	                // screenshots still show recognizable content at chip size.
421	                var thumb = new System.Windows.Shapes.Rectangle
422	                {
423	                    Width = AttachmentThumbnailSize,
424	                    Height = AttachmentThumbnailSize,
425	                    RadiusX = 3,
426	                    RadiusY = 3,
427	                    Margin = new Thickness(0, 0, 6, 0),
428	                    VerticalAlignment = VerticalAlignment.Center,
429	                    Fill = new System.Windows.Media.ImageBrush(bitmap)
430	                    {
431	                        Stretch = System.Windows.Media.Stretch.UniformToFill
432	                    }
433	                };
434	                System.Windows.Media.RenderOptions.SetBitmapScalingMode(
435	                    thumb, System.Windows.Media.BitmapScalingMode.HighQuality);
436	
437	                return thumb;
438	            }
439	            catch (Exception ex)
440	            {
441	                Debug.WriteLine($"CreateAttachmentThumbnail error for '{path}': {ex.Message}");
442	                return null;
443	            }
444	        }
445	
446	        /// <summary>
447	        /// Width and height of a Modern image attachment card. The picture fills the whole card:
448	        /// the file name it used to show under it (image_1.png…) told the user nothing.
449	        /// </summary>
450	        private const int AttachmentCardWidth = 120;
451	        private const int AttachmentCardImageHeight = 88;
452	
453	        /// <summary>
454	        /// Modern icon style's attachment for an image: a card showing the whole picture scaled down
455	        /// (no crop, so a screenshot stays recognizable) and the ✕ in its corner. Same behavior as
456	        /// the chip: click opens the file, hover anywhere on the card shows the large preview.
457	        /// Null when the image can't be decoded, so the caller falls back to the plain chip.
458	        /// </summary>
459	        private Border CreateAttachmentCard(string path, Action<string> onRemove)
460	        {
461	            try
462	            {
463	                // Decoded at 2x the display width so the card stays crisp on a 200% DPI monitor.
464	                var bitmap = UI.ImagePreview.LoadBitmap(path, AttachmentCardWidth * 2);
465	                if (bitmap == null) return null;
466	
467	                var card = new Border
468	                {
469	                    Width = AttachmentCardWidth,
470	                    CornerRadius = new CornerRadius(6),
471	                    BorderThickness = new Thickness(1),
472	                    Padding = new Thickness(4),
473	                    Margin = new Thickness(0, 2, 6, 2),
474	                    Cursor = Cursors.Hand,
475	                    Tag = path
476	                };
477	                card.SetResourceReference(Border.BackgroundProperty, Microsoft.VisualStudio.Shell.VsBrushes.ToolWindowBackgroundKey);
478	                card.SetResourceReference(Border.BorderBrushProperty, Microsoft.VisualStudio.Shell.VsBrushes.ToolWindowBorderKey);
479	
480	                card.MouseLeftButtonUp += (s, e) =>
481	                {
482	                    if (e.OriginalSource is Button) return;
483	                    UI.ImagePreview.OpenFile(path);
484	                };
485	
486	                var grid = new Grid { Height = AttachmentCardImageHeight };
487	
488	                var image = new Image
489	                {
490	                    Source = bitmap,
491	                    Stretch = System.Windows.Media.Stretch.Uniform,
492	                    StretchDirection = StretchDirection.DownOnly,
493	                    HorizontalAlignment = HorizontalAlignment.Center,
494	                    VerticalAlignment = VerticalAlignment.Center
495	                };
496	                System.Windows.Media.RenderOptions.SetBitmapScalingMode(
497	                    image, System.Windows.Media.BitmapScalingMode.HighQuality);
498	                grid.Children.Add(image);
499	
500	                // Over the picture's top-right corner, on its own background so it stays visible on
501	                // any image.
502	                var removeBtn = new Button
503	                {
504	                    Style = (Style)FindResource("ChipRemoveButton"),
505	                    Width = 18,
506	                    Height = 18,
507	                    Margin = new Thickness(0),
508	                    HorizontalAlignment = HorizontalAlignment.Right,
509	                    VerticalAlignment = VerticalAlignment.Top,
510	                    ToolTip = L("Remove"),
511	                    Tag = path
512	                };
513	                removeBtn.Click += (s, e) => onRemove?.Invoke((string)((Button)s).Tag);
514	                grid.Children.Add(removeBtn);
515	
516	                card.Child = grid;
517	                UI.ImagePreview.AttachPreviewToolTip(card, path);
518	                return card;
519	            }
520	            catch (Exception ex)
521	            {
522	                Debug.WriteLine($"CreateAttachmentCard error for '{path}': {ex.Message}");
523	                return null;
524	            }
525	        }
526	
527	        /// <summary>
528	        /// Clears all attached images
529	        /// </summary>
530	        private void ClearAttachedImages()
531	        {
532	            attachedImagePaths.Clear();
533	            UpdateImageDropDisplay();
534	        }
535	
536	        /// <summary>
537	        /// Restores file attachments from a history entry, adding only files that still exist on disk
538	        /// </summary>
539	        /// <param name="filePaths">The file paths to restore</param>
540	        private void RestoreFilesFromHistory(List<string> filePaths)
541	        {
542	            attachedImagePaths.Clear();
543	
544	            if (filePaths != null)
545	            {
546	                foreach (string path in filePaths)
547	                {
548	                    if (!string.IsNullOrEmpty(path) && File.Exists(path))
549	                    {
550	                        attachedImagePaths.Add(path);
551	                    }
552	                }
553	            }
554	
555	            UpdateImageDropDisplay();
556	        }
557	
558	        /// <summary>
559	        /// Checks if a file path represents an image file
560	        /// </summary>
561	        /// <param name="filePath">The file path to check</param>
562	        /// <returns>True if the file is an image, false otherwise</returns>
563	        private bool IsImageFile(string filePath)
564	        {
565	            return UI.ImagePreview.IsImageFile(filePath);
566	        }
567	
568	        #endregion
569	    }
570	}
